// Removed unused fs and path imports
import crypto from 'crypto';

/**
 * Verify the HMAC token generated by our verify function
 */
function verifyToken(token) {
  try {
    const parts = token.split('.');
    if (parts.length !== 2) return null;
    
    const [payloadBase64, signature] = parts;

    const secret = process.env.EBOOK_DOWNLOAD_SECRET;
    if (!secret) {
      console.error('Missing EBOOK_DOWNLOAD_SECRET for token verification');
      return null;
    }

    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(payloadBase64)
      .digest('base64url');

    if (signature !== expectedSignature) {
      return null; // Invalid signature
    }

    const payload = JSON.parse(Buffer.from(payloadBase64, 'base64url').toString('utf8'));
    return payload;

  } catch (error) {
    console.error('Token verification error:', error);
    return null;
  }
}

export const handler = async (event, context) => {
  if (event.httpMethod !== 'GET') {
    return { statusCode: 405, body: 'Method Not Allowed' };
  }

  try {
    const token = event.queryStringParameters?.token;
    
    if (!token) {
      return { statusCode: 403, body: 'Forbidden: Missing secure access token.' };
    }

    const payload = verifyToken(token);

    if (!payload) {
      return { statusCode: 403, body: 'Forbidden: Invalid or tampered access token.' };
    }

    // Check expiration securely
    const now = Math.floor(Date.now() / 1000);
    if (payload.exp < now) {
      return { 
        statusCode: 403, 
        body: 'Forbidden: This download link has expired. Please contact support if you need a new link.' 
      };
    }

    // Token is strictly valid and not expired.
    
    // Read the Google Drive URL from environment variables
    const googleDriveUrl = process.env.EBOOK_GOOGLE_DRIVE_URL;
    
    if (!googleDriveUrl) {
      console.error('CRITICAL: EBOOK_GOOGLE_DRIVE_URL environment variable is missing.');
      return { statusCode: 500, body: 'Internal Server Error: Ebook link is not configured.' };
    }

    // Redirect the user to the Google Drive file
    return {
      statusCode: 302,
      headers: {
        Location: googleDriveUrl,
        'Cache-Control': 'no-cache, no-store, must-revalidate',
      },
      body: 'Redirecting to secure download...'
    };

  } catch (error) {
    console.error('Secure download error:', error);
    return { statusCode: 500, body: 'Internal Server Error' };
  }
};
